c.save();c.font=`${weight} ${size}px ${CF}`;c.textBaseline='alphabetic';c.textAlign='left';let k=0;
L.lines.forEach((line,li)=>{
const lx=o.align==='center'?box.x+(box.w-line.w)/2:o.align==='right'?box.x+box.w-line.w:box.x,base=y0+li*size*lh+size*.9;
line.words.forEach((word,wi)=>{
const idx=k++,a=clamp((lt-t0-idx*stag)/.42);if(a<=0)return;
const hot=em.has(idx),x=lx+word.x,e=eOut5(a);
if(hot){const nextHot=wi<line.words.length-1&&em.has(idx+1),pw=clamp((lt-t0-idx*stag-.06)/.26),pad=size*.1;
c.fillStyle=o.ac;c.fillRect(x-pad,base-size*.86,(word.w+pad*2+(nextHot?L.sp:0))*eOut(pw),size*1.1);}
let str=word.s;const num=/^([1-9]\d{1,5})(\D*)$/.exec(str);
if(num&&o.count!==false){const cp=eOut(clamp((lt-t0-idx*stag)/.9));str=String(Math.round(Number(num[1])*cp)).padStart(num[1].length,'0')+num[2];if(cp>=1)str=word.s;}
c.save();c.globalAlpha*=Math.min(1,a*2.5);
if(o.mode==='rise'){c.beginPath();c.rect(x-size,base-size*1.02,word.w+size*2,size*1.3);c.clip();c.translate(0,(1-e)*size*1.05);}
else{const s=lerp(1.32,1,e);c.translate(x+word.w/2,base-size*.35);c.scale(s,s);c.rotate((1-e)*(idx%2?-.07:.07));c.translate(-(x+word.w/2),-(base-size*.35));}
c.fillStyle=hot?o.onAc:o.color;c.fillText(str,x,base);c.restore();
});
});
