/* ui.js */
'use strict';
const PAD = 14, FPS_TC = 30;
const TL = { pps: 40, zoom: 1, thumbs: {}, thumbTimer: 0, trSel: 'chop' };
function tc(t) { t = Math.max(0, t || 0); const f = Math.floor((t % 1) * FPS_TC), s = Math.floor(t) % 60, m = Math.floor(t / 60) % 60, h = Math.floor(t / 3600); return [h, m, s, f].map(v => String(v).padStart(2, '0')).join(':'); }
function updateTime() { $('timeLbl').textContent = tc(S.t) + ' / ' + tc(S.tl.total); const sc = $('scrub'); if (sc && document.activeElement !== sc) sc.value = S.tl.total ? Math.round(S.t / S.tl.total * 1000) : 0; }
function calcPps() { const avail = Math.max(300, $('tlScroll').clientWidth - PAD * 2 - 10); const total = S.tl.total || 1; TL.pps = avail / total * TL.zoom; return TL.pps; }
function timeX(t) { return PAD + Math.max(0, t) * TL.pps; }
function xTime(x) { return clamp((x - PAD) / TL.pps, 0, S.tl.total); }
function renderTrack() {
const tr = $('track'); if (!tr) return; tr.innerHTML = ''; calcPps(); const W_ = PAD * 2 + (S.tl.total || 1) * TL.pps; $('lanes').style.width = Math.max($('tlScroll').clientWidth, W_) + 'px';
const timing = {}; S.tl.items.forEach(it => timing[it.sc.id] = it);
let off = S.tl.total; // cảnh tắt: xếp sau cùng, mờ
S.proj.scenes.forEach(sc => { const def = SCENES[sc.type]; if (!def) return; let it = timing[sc.id]; const d = it ? it.d : (parseFloat(sc.dur) || def.dur || 2); const st = it ? it.start : (off += 0, off);
if (!it) off += d;
const b = document.createElement('div'); b.className = 'blk' + (sc.id === S.sel ? ' sel' : '') + (sc.on === false ? ' off' : ''); b.style.setProperty('--gc', gcol(def.group));
b.style.left = timeX(st) + 'px'; b.style.width = Math.max(8, d * TL.pps - 2) + 'px'; b.draggable = true; b.dataset.id = sc.id;
const th = TL.thumbs[sc.id]; if (th && th.url) b.style.backgroundImage = `url(${th.url})`;
b.innerHTML = `<span class="nm"></span><span class="du">${d.toFixed(1)}s${sc.voice.text && S.proj.voiceOn ? ' · 🎙' : ''}</span>${sc.trans && sc.trans !== 'mo' ? '<span class="tr" title="Có chuyển cảnh"></span>' : ''}`;
b.querySelector('.nm').textContent = (sc.type === 'ai_design' ? (sc.p.heading || def.name) : sc.vbt && sc.vbt.title ? '✏️ ' + sc.vbt.title : def.name).replace(/^3D: /, ''); b.title = def.name;
const x = document.createElement('button'); x.className = 'bx'; x.title = 'Xoá cảnh này (Ctrl+Z để lấy lại)'; x.textContent = '✕';
x.onclick = e => { e.stopPropagation(); sceneAction(sc, 'del'); toast('Đã xoá cảnh. Bấm Ctrl+Z nếu muốn lấy lại.'); }; b.appendChild(x);
b.oncontextmenu = e => { e.preventDefault(); select(sc.id); blkMenu(e, sc); };
b.onclick = e => { select(sc.id); if (it) seek(it.start + clamp(e.offsetX / b.offsetWidth, 0, .999) * it.d); };
b.ondragstart = e => { dragId = sc.id; b.classList.add('drag'); e.dataTransfer.effectAllowed = 'move'; };
b.ondragend = () => { dragId = null; b.classList.remove('drag'); tr.querySelectorAll('.dropL').forEach(x => x.classList.remove('dropL')); };
b.ondragover = e => { e.preventDefault(); tr.querySelectorAll('.dropL').forEach(x => x.classList.remove('dropL')); b.classList.add('dropL'); };
b.ondrop = e => { e.preventDefault(); if (!dragId || dragId === sc.id) return; const arr = S.proj.scenes, from = arr.findIndex(x => x.id === dragId); const [m] = arr.splice(from, 1); const to = arr.findIndex(x => x.id === sc.id); arr.splice(to, 0, m); rebuild(); markDirty(); };
tr.appendChild(b); });
renderRuler(); renderLanes(); movePlayhead(); updateSteps(); queueThumbs();
if ($('tGiong') && $('tGiong').classList.contains('on')) renderVoiceList();
}
function blkMenu(e, sc) {
document.querySelectorAll('.blkmenu').forEach(m => m.remove());
const m = document.createElement('div'); m.className = 'blkmenu'; m.style.left = e.clientX + 'px'; m.style.top = Math.max(8, e.clientY - 150) + 'px';
const items = [['🗑 Xoá cảnh này', () => { sceneAction(sc, 'del'); toast('Đã xoá cảnh. Ctrl+Z để lấy lại.'); }], ['⧉ Nhân bản', () => sceneAction(sc, 'dup')], [sc.on === false ? '👁 Bật lại cảnh' : '⊘ Tắt cảnh (giữ lại, không xuất)', () => sceneAction(sc, 'toggle')],
['🗑 Xoá các cảnh từ đây về sau', () => { const i = S.proj.scenes.indexOf(sc); const n = S.proj.scenes.length - i; S.proj.scenes.splice(i); S.sel = S.proj.scenes[i - 1]?.id || null; rebuild(); renderInspector(); markDirty(); toast(`Đã xoá ${n} cảnh. Ctrl+Z để lấy lại.`); }]];
items.forEach(([t, fn]) => { const b = document.createElement('button'); b.textContent = t; b.onclick = () => { m.remove(); fn(); }; m.append(b); });
document.body.append(m); setTimeout(() => document.addEventListener('click', () => m.remove(), { once: true }), 0);
}
function renderRuler() {
const r = $('ruler'); r.innerHTML = ''; const total = S.tl.total || 0; const steps = [.5, 1, 2, 5, 10, 15, 30, 60]; let st = steps.find(s => s * TL.pps >= 70) || 60; const minor = st / 5;
let h = ''; for (let t = 0; t <= total + 1e-6; t += minor) { const big = Math.abs(t / st - Math.round(t / st)) < 1e-6; h += `<i class="${big ? 'b' : ''}" style="left:${timeX(t)}px"></i>`; if (big) { const m = Math.floor(t / 60), s = Math.round(t % 60 * 10) / 10; h += `<span style="left:${timeX(t)}px">${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}</span>`; } }
r.innerHTML = h;
}
function renderLanes() {
const lv = $('laneVoice'); if (!lv) return; lv.innerHTML = ''; if (!S.proj.voiceOn) { drawWave(); return; }
S.tl.items.forEach(it => { const sc = it.sc, t = (sc.voice.text || '').trim() || (sc.voice.rec ? '🎙 giọng ghi âm' : ''); if (!t) return; const vb = typeof voiceBufOf === 'function' ? voiceBufOf(sc) : null, v = vb ? { buf: vb } : null;
const c = document.createElement('div'); c.className = 'vchip' + (sc.voice.auto ? ' auto' : '') + (v && v.buf ? '' : ' wait'); const t0 = it.start + .3, dur = v && v.buf ? v.buf.duration : Math.max(.5, it.d - .5);
c.style.left = timeX(t0) + 'px'; c.style.width = Math.max(18, Math.min(dur, it.start + it.d - t0) * TL.pps - 2) + 'px'; c.textContent = t; c.title = t + (v && v.buf ? '' : ' (chưa đọc giọng)');
c.onclick = () => { select(sc.id); showPane('tGiong'); renderVoiceList(sc.id); seek(it.start); }; lv.append(c); });
drawWave();
}
function movePlayhead() { const ph = $('playhead'); if (!ph) return; ph.style.left = timeX(S.t) + 'px'; if (S.playing) { const sc = $('tlScroll'), x = timeX(S.t); if (x < sc.scrollLeft + 20 || x > sc.scrollLeft + sc.clientWidth - 40) sc.scrollLeft = x - 60; } }
function drawWave() {
const cv = $('laneWave'); if (!cv || !S.tl || !S.tl.items.length) return; const w = Math.max(10, $('lanes').offsetWidth), h = 50, dpr = window.devicePixelRatio || 1; cv.width = w * dpr; cv.height = h * dpr; cv.style.width = w + 'px';
const g = cv.getContext('2d'); g.setTransform(dpr, 0, 0, dpr, 0, 0); g.clearRect(0, 0, w, h); const col = getComputedStyle(document.documentElement).getPropertyValue('--c-wave').trim() || '#14B8A6';
const buf = S.audio.buf && S.audio.key === audioKey() ? S.audio.buf : null; const x0 = timeX(0), x1 = timeX(S.tl.total);
g.fillStyle = col; g.globalAlpha = .12; g.fillRect(x0, 4, x1 - x0, h - 8); g.globalAlpha = 1;
if (!buf) { const pr = S.audio.prog; g.font = '600 11px ' + getComputedStyle(document.body).fontFamily;
if (pr != null) { const bw = Math.min(260, Math.max(60, x1 - x0 - 16)); g.fillStyle = col; g.globalAlpha = .25; g.fillRect(x0 + 8, h - 14, bw, 6); g.globalAlpha = 1; g.fillRect(x0 + 8, h - 14, bw * pr / 100, 6); }
g.fillStyle = col; g.fillText(pr != null ? `Đang dựng âm thanh ${pr}% · ${S.audio.progLbl || ''}` : 'Âm thanh chưa dựng (bấm ▶ hoặc chờ vài giây)', x0 + 8, h / 2 - 2); return; }
const d0 = buf.getChannelData(0), sr = buf.sampleRate, step = 2; g.fillStyle = col;
for (let x = Math.floor(x0); x < x1; x += step) { const t = xTime(x), i0 = Math.floor(t * sr), n = Math.max(1, Math.floor(step / TL.pps * sr)); let m = 0; for (let i = i0; i < i0 + n && i < d0.length; i += 16) m = Math.max(m, Math.abs(d0[i])); const hh = Math.max(1, Math.min(1, m * 1.4) * (h - 10)); g.fillRect(x, h / 2 - hh / 2, step - .6, hh); }
}
function queueThumbs() { clearTimeout(TL.thumbTimer); TL.thumbTimer = setTimeout(makeThumbs, 700); }
function thumbKey(it) { const m = imgMedia((it.sc.p || {}).img); return JSON.stringify([it.sc.type, it.sc.p, S.proj.theme, S.proj.brand.color, S.proj.product, m && m.url, (S.proj.media || []).length, Math.round(it.d * 10)]); }
function makeThumbs() {
if (S.playing || S.exporting || !S.tl.items.length) { if (!S.exporting) TL.thumbTimer = setTimeout(makeThumbs, 1500); return; }
const todo = S.tl.items.filter(it => !TL.thumbs[it.sc.id] || TL.thumbs[it.sc.id].key !== thumbKey(it)); if (!todo.length) return;
const cv = TL.tcv || (TL.tcv = mk(108, 192)), prev = E.preview;
try { setupCanvas(cv, .1); E.preview = false;
todo.slice(0, 6).forEach(it => { drawFrame(it.start + it.d * .6, S.tl); TL.thumbs[it.sc.id] = { key: thumbKey(it), url: cv.toDataURL('image/jpeg', .7) }; });
} catch (e) { console.warn('thumb', e); } finally { E.preview = prev; setupCanvas($('cv'), PERF.r); S.dirty = true; }
S.tl.items.forEach(it => { const b = $('track').querySelector(`.blk[data-id="${it.sc.id}"]`), th = TL.thumbs[it.sc.id]; if (b && th) b.style.backgroundImage = `url(${th.url})`; });
if (todo.length > 6) queueThumbs();
}
const HIST = { stack: [], pos: -1, busy: false, t: 0 };
function histPush() { if (HIST.busy || !S.proj) return; const j = JSON.stringify(S.proj); if (HIST.stack[HIST.pos] === j) return; HIST.stack = HIST.stack.slice(0, HIST.pos + 1); HIST.stack.push(j); if (HIST.stack.length > 80) HIST.stack.shift(); HIST.pos = HIST.stack.length - 1; histBtns(); }
