for (let L = lo + 1; L <= hi; L++) { const bpm = 60 / (L * dt), w = Math.exp(-Math.pow(Math.log2(bpm / 120), 2) / (2 * .5 * .5)), sc = ac[L] * w; if (sc > best) { best = sc; bl = L; } }
