let P = bl * dt, bestS = -1, PH = 0;
for (let p = P - dt; p <= P + dt; p += .0005) for (let ph = 0; ph < p; ph += dt) { const s = comb(p, ph); if (s > bestS) { bestS = s; P = p; PH = ph; } }
