const w = document.querySelector('#folderCard .tick'); msg = msg.replace(/[^\s/\\]{27,}/g, x => shortName(x)); if (w) w.textContent = `⏱ đã chạy ${mm}:${ss}${msg ? ' · ' + msg : ''}`;
