const fsteps = (n, msg) => `<b>🎬 Đang tự dựng video từ thư mục</b><ol class="fst">${['Nhập video vào thư viện', 'Nghe tiếng từng video', 'AI xem hình (video + ảnh), chọn cảnh và dựng'].map((t, i) => `<li class="${i < n ? 'ok' : i === n ? 'now' : ''}">${i < n ? '✓' : i === n ? '●' : '○'} ${t}</li>`).join('')}</ol><p class="hint">${msg || ''}</p><p class="tick"></p>`;
