st.textContent = `Đang nhập ${i + 1}/${files.length}: ${shortName(f.name)}${isV ? ' (giữ nguyên chất lượng gốc)' : ''}…`; jobSet(st.textContent, i / files.length); fcard(fsteps(0, st.textContent));
