const isScript = txt.split(/\s+/).length > 45 || /\n.*\n/.test(txt);
const body = isScript ? { script: txt, topic: '', notes: $('vbNotes').value } : { topic: txt, seconds: +$('vbSecs').value, notes: $('vbNotes').value };
