const sents = text.split(/(?<=[.!?…;:])\s+/).map(s => s.trim()).filter(Boolean), out = [];
for (const s of sents) {
if (s.length <= max) { out.push(s); continue; }
let buf = '';
for (const p of s.split(/(?<=,)\s+/).map(x => x.trim()).filter(Boolean)) {
const cand = (buf + ' ' + p).trim(); if (cand.length <= max) { buf = cand; continue; }
if (buf) out.push(buf);
if (p.length > max) { const pcs = capBalance(p, max); pcs.slice(0, -1).forEach(x => out.push(x)); buf = pcs[pcs.length - 1]; }
else buf = p;
}
if (buf) out.push(buf);
}
const merged = [];
for (const part of out) {
const last = merged[merged.length - 1], endS = last != null && /[.!?…]$/.test(last);
const ok = last != null && last.length + 1 + part.length <= max + 10 && (endS ? (part.length < 14 || last.length < 14) : (part.length < CAP.min || last.length < CAP.min));
if (ok) merged[merged.length - 1] = last + ' ' + part; else merged.push(part);
}
