const used = new Set(); (HH.story.characters || []).forEach(c => { if (c.voice) return; const pool = L.filter(v => (c.gender === 'female') === fem(v)); const pick = pool.find(v => !used.has(v.id)) || pool[0] || L[0]; if (pick) { c.voice = pick.id; used.add(pick.id); } });
