$('citOpen').onclick = async () => { $('citStat').textContent = 'Đang mở CIT Voice Studio, chờ mô hình sẵn sàng (≤ 1 phút)…'; try { const r = await api('/api/cit/start', { wait: 90 }); await refreshVoices(); toast(r.cit ? 'CIT Voice Studio đã sẵn sàng' : 'Chưa mở được CIT Voice Studio', !r.cit); } catch (e) { toast(e.message, true); } };
$('citRefresh').onclick = () => refreshVoices(true);
$('aVoiceFx').onchange = () => { S.proj.voiceFx = $('aVoiceFx').value; rebuild(); markDirty(); renderVoiceList(); voiceAll(true); };
$('vfxTry').onclick = async () => { const sc = curScene() || S.proj.scenes.find(s => (s.voice.text || '').trim()); if (!sc || !(sc.voice.text || '').trim()) return toast('Chọn cảnh có lời đọc trước'); try { $('vfxTry').disabled = true; const r = await synth(sc); playBuf(r.buf); rebuild(); } catch (e) { toast(e.message, true, 6000); } finally { $('vfxTry').disabled = false; } };
