const phone = r.phone || '0961.022.023', seller = r.seller || '';
const bad = !r.licensed && (r.trial_expired || false);
$('licSt').className = 'prostat' + ((r.licensed && !near) ? '' : ' no');
const hanTxt = r.het ? ` · hạn ${r.het}${typeof r.days_left === 'number' ? ' (còn ' + r.days_left + ' ngày)' : ''}` : ' · vĩnh viễn';
$('licSt').textContent = r.owner ? 'Chủ app' : r.licensed ? `Đã kích hoạt · ${r.name || ''}${hanTxt}`
: r.trial_expired ? 'Hết hạn dùng thử' : `Dùng thử · còn ${typeof r.trial_days_left === 'number' ? r.trial_days_left : 15} ngày`;
$('licInfo').innerHTML = r.licensed
? (r.owner ? 'Máy của chủ app (có khoá riêng) — không cần kích hoạt.'
: (near ? `⚠ Bản quyền sắp hết hạn (còn ${r.days_left} ngày). Liên hệ ${seller ? seller + ' · ' : ''}<b>${phone}</b> để gia hạn, dán mã mới vào ô dưới.` : 'Cảm ơn bạn đã mua bản quyền. Video xuất không còn chữ mờ.'))
: r.trial_expired
? `⛔ Đã hết hạn dùng thử — chưa xuất được video. Liên hệ <b>${seller || 'người bán'} · ${phone}</b> để mua bản quyền. Gửi "Mã máy" bên trên, nhận mã kích hoạt rồi dán vào ô dưới.`
: `Đang dùng thử (còn ${typeof r.trial_days_left === 'number' ? r.trial_days_left : 15} ngày). Video xuất có chữ mờ. Mua bản quyền: gửi "Mã máy" cho ${seller || 'người bán'} · <b>${phone}</b>.`;
